const names = IN.names;
const w_sc = IN.w_sc;
const h_sc = IN.h_sc;

// 1. Define the maximum percentage of randomness (e.g., 5%)
const jitterFactor = 0; 
const scalejitterFactor = 0; 

// 2. Helper function to generate a random multiplier between (1 - factor) and (1 + factor)
function getRandomMultiplier(factor) {
    // Math.random() gives 0 to 1. 
    // This formula returns a value between 0.95 and 1.05 (if factor is 0.05)
    return 1 - factor + (Math.random() * factor * 2);
}

let xywh_list = [];

for(let i = 0; i < names.length; i++) {
   let name = names[i];
   let comp = UI.get(name);

   if(comp) {
       // 3. Apply the random multiplier to each coordinate/dimension
       let jittered_x = comp.x * getRandomMultiplier(jitterFactor);
       let jittered_y = comp.y * getRandomMultiplier(jitterFactor);
       let jittered_w = comp.w * getRandomMultiplier(scalejitterFactor);
       let jittered_h = comp.h * getRandomMultiplier(scalejitterFactor);

       // Scale the jittered coordinates and dimensions
       xywh_list.push([
           jittered_x * w_sc, 
           jittered_y * h_sc, 
           jittered_w * w_sc, 
           jittered_h * h_sc
       ]);
   } else {
       ENGINE.log("Cannot Get bboxes of " + name);
   }
}

OUT.bboxes = xywh_list;

